('Orman Yetiştiriciliği',11,'Temel Ormancılık Bilgisi',2,16),('Orman Yetiştiriciliği',12,'Ağaçlandırma',2,16),('Orman Yetiştiriciliği',12,'Silvikültür Tekniği',3,16),('Orman Yetiştiriciliği',12,'Odun Dışı Ürünler',2,16),
('Sebze Yetiştiriciliği',11,'Alternatif Tarım Teknikleri',2,17),('Sebze Yetiştiriciliği',12,'Örtü Altı Sistemleri',2,17),('Sebze Yetiştiriciliği',12,'Yazlık Sebzeler',2,17),('Sebze Yetiştiriciliği',12,'Kışlık Sebzeler',3,17),
('Seracılık',11,'Alternatif Tarım Teknikleri',2,18),('Seracılık',12,'Örtü Altı Sistemleri',2,18),('Seracılık',12,'Örtü Altı Yetiştiriciliği',5,18),
('Tarla Bitkileri Yetiştiriciliği',11,'Yemeklik Tane Baklagiller',2,19),('Tarla Bitkileri Yetiştiriciliği',12,'Tahıllar',4,19),('Tarla Bitkileri Yetiştiriciliği',12,'Çayır-Mera ve Yem Bitkileri',3,19),
('Tıbbi Aromatik Bitkiler Yetiştiriciliği',11,'Tıbbi Aromatik Bitkiler',2,20),('Tıbbi Aromatik Bitkiler Yetiştiriciliği',12,'Tek ve Çok Yıllık Tıbbi Aromatik Bitkilerin Üretimi',4,20),('Tıbbi Aromatik Bitkiler Yetiştiriciliği',12,'Tıbbi Aromatik Bitkilerde Hasat ve Drog Hazırlama',3,20))
