select distinct name,'uygulama' from d on conflict(name) do nothing;

with d(branch_name,grade_level,name,h,page) as (values
('Endüstri Bitkileri Yetiştiriciliği',11,'Yağ Bitkileri',2,13),('Endüstri Bitkileri Yetiştiriciliği',12,'Nişasta ve Şeker Bitkileri',4,13),('Endüstri Bitkileri Yetiştiriciliği',12,'Lif ve Keyf Bitkileri',3,13),
('Mantar Yetiştiriciliği',11,'Mantar Üretim Hazırlıkları',2,14),('Mantar Yetiştiriciliği',12,'Kompost Yapım Tekniği',3,14),('Mantar Yetiştiriciliği',12,'Mantar Üretimi',4,14),
('Meyve Yetiştiriciliği',11,'Fidan Üretimi',2,15),('Meyve Yetiştiriciliği',12,'Meyve Ağaçlarında Budama ve Terbiye',2,15),('Meyve Yetiştiriciliği',12,'Ilıman İklim Meyveleri',3,15),('Meyve Yetiştiriciliği',12,'Sıcak İklim Meyveleri',2,15),
('Orman Yetiştiriciliği',11,'Temel Ormancılık Bilgisi',2,16),('Orman Yetiştiriciliği',12,'Ağaçlandırma',2,16),('Orman Yetiştiriciliği',12,'Silvikültür Tekniği',3,16),('Orman Yetiştiriciliği',12,'Odun Dışı Ürünler',2,16),
('Sebze Yetiştiriciliği',11,'Alternatif Tarım Teknikleri',2,17),('Sebze Yetiştiriciliği',12,'Örtü Altı Sistemleri',2,17),('Sebze Yetiştiriciliği',12,'Yazlık Sebzeler',2,17),('Sebze Yetiştiriciliği',12,'Kışlık Sebzeler',3,17),
('Seracılık',11,'Alternatif Tarım Teknikleri',2,18),('Seracılık',12,'Örtü Altı Sistemleri',2,18),('Seracılık',12,'Örtü Altı Yetiştiriciliği',5,18),
('Tarla Bitkileri Yetiştiriciliği',11,'Yemeklik Tane Baklagiller',2,19),('Tarla Bitkileri Yetiştiriciliği',12,'Tahıllar',4,19),('Tarla Bitkileri Yetiştiriciliği',12,'Çayır-Mera ve Yem Bitkileri',3,19),
('Tıbbi Aromatik Bitkiler Yetiştiriciliği',11,'Tıbbi Aromatik Bitkiler',2,20),('Tıbbi Aromatik Bitkiler Yetiştiriciliği',12,'Tek ve Çok Yıllık Tıbbi Aromatik Bitkilerin Üretimi',4,20),('Tıbbi Aromatik Bitkiler Yetiştiriciliği',12,'Tıbbi Aromatik Bitkilerde Hasat ve Drog Hazırlama',3,20)),v(schedule_variant) as (values('USTALIK'),('DIPLOMA'))
insert into official_course_schedule_catalog(effective_academic_year,school_type,program_type,grade_level,course_id,category,hour_options,max_selections,repeat_across_years,source_file_name,source_note,active,imported_at,updated_at,field_name,branch_name,parsed_constraints,source_decision_no,source_page,source_section,parser_confidence,needs_review,schedule_variant)
select '2026-2027','MESEM','MESEM',d.grade_level,c.id,'uygulama',array[d.h],1,true,'https://meslek.meb.gov.tr/upload/cop11_mem/2022_tarim_mem_cop.pdf','2023-3 yaşayan MESEM Tarım çizelgesi; parantezli saatler DIPLOMA fark dersidir.',true,now(),now(),'Tarım',d.branch_name,'{"enterpriseDays":4,"enterpriseHoursPerDay":8}'::jsonb,'2023-3',d.page,'HAFTALIK DERS ÇİZELGESİ',1,false,v.schedule_variant
from d join course_catalog c on c.name=d.name cross join v
where not exists(select 1 from official_course_schedule_catalog x where x.active and x.effective_academic_year='2026-2027' and x.school_type='MESEM' and coalesce(x.program_type,'')='MESEM' and x.field_name='Tarım' and x.branch_name=d.branch_name and x.grade_level=d.grade_level and x.schedule_variant=v.schedule_variant and x.course_id=c.id);
commit;